// The built-in sounds an empty pool slot plays (sample_pool.h): short
// synthesised voice-like phrases (formant vowels with a pitch contour), mono
// int16 at kPoolRate, in flash. Generated by host/tools/gen_rom_samples.cpp
// into rom_samples_data.cpp (do not edit that file by hand).
#pragma once
#include <cstdint>

#include "sample_format.h"

namespace pg {
namespace sampler {

struct RomSample {
  const int16_t* data;
  uint32_t length;          // samples
  const char* name;         // <= kNameLen characters
  uint16_t peak;
  const int8_t (*overview)[2];   // kOverviewCols pairs
};

constexpr int kRomCount = 3;
extern const RomSample kRom[kRomCount];

}  // namespace sampler
}  // namespace pg
